import { test, expect } from '@playwright/test';

test.describe('Google OAuth Login Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully authenticate with Google OAuth and redirect to home page', async ({ page }) => {
    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Verify Google OAuth modal appears
    const authModal = page.locator('[data-testid="auth-modal"]');
    await expect(authModal).toBeVisible();

    // Verify Google sign-in button is visible
    const googleSignInButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(googleSignInButton).toBeVisible();

    // Click Google sign-in button
    await googleSignInButton.click();

    // Verify user is redirected to home page
    const homePage = page.getByRole('main');
    await expect(homePage).toBeVisible();

    // Verify welcome message is displayed
    const welcomeMessage = page.getByText(/welcome, user name/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user profile icon is visible
    const userProfileIcon = page.getByRole('img', { name: /user profile/i });
    await expect(userProfileIcon).toBeVisible();

    // Verify logout button is visible
    const logoutButton = page.getByRole('button', { name: /log out/i });
    await expect(logoutButton).toBeVisible();
  });

  test('should handle failed Google OAuth authentication and display error message', async ({ page }) => {
    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Verify Google OAuth modal appears
    const authModal = page.locator('[data-testid="auth-modal"]');
    await expect(authModal).toBeVisible();

    // Verify Google sign-in button is visible
    const googleSignInButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(googleSignInButton).toBeVisible();

    // Click Google sign-in button
    await googleSignInButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is still visible for retry
    await expect(loginButton).toBeVisible();

    // Verify user is not redirected to home page
    const homePage = page.getByRole('main');
    await expect(homePage).not.toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /try again/i });
    await expect(retryButton).toBeVisible();
  });
});
